import swtr.*;
import java.io.FileOutputStream;

TransformFunction transform = (data, size) -> {
    for (int i = 0; i < size; ++i)
        if (data[i] >= 'a' && data[i] <= 'z') data[i] -= 32;
};

SwtrRingBuffer rb = new SwtrRingBuffer(4, BufferStatus.READYFORREAD, 4096, null, transform);
rb.setReadFd(0);  // stdin

// Open output file and get its FD (platform-dependent)
try (FileOutputStream fos = new FileOutputStream("output.txt")) {
    rb.setWriteFd(/* file descriptor */);
}

// Set MD5 checksums on all slots
for (int i = 0; i < 4; ++i) {
    rb.setChecksumAlg(i, ChecksumAlgorithm.MD5);
}

rb.start();
rb.awaitTermination();
rb.stop();
